mapper.select:
SELECT id, agent_code AS agentCode, agent_name AS agentName, agent_type AS agentType, agent_describe AS agentDescribe, agent_show AS agentShow, model_id AS modelId, model_select_policy AS modelSelectPolicy, knowledge_scope_policy AS knowledgeScopePolicy, enable_thinking AS enableThinking, system_prompt AS systemPrompt, welcome_message AS welcomeMessage, suggested_questions AS suggestedQuestions, execution_policy AS executionPolicy, skill_names AS skillNames, knowledge_ids AS knowledgeIds, status, remark, create_time AS createTime, update_time AS updateTime FROM agent_info
AND del_flag = 0
AND agent_name LIKE CONCAT('%', #{bo.agentName}, '%')
AND agent_code LIKE CONCAT('%', #{bo.agentCode}, '%')
AND agent_type = #{bo.agentType}
AND status = #{bo.status}
AND model_id = #{bo.modelId}
ORDER BY update_time DESC, id DESC
